CREATE TABLE commercial_promotion(tenant_id UUID NOT NULL,branch_id UUID NOT NULL,product_id UUID NOT NULL,percent NUMERIC(5,2) NOT NULL CHECK(percent>0 AND percent<100),starts_on DATE NOT NULL,ends_on DATE NOT NULL CHECK(ends_on>=starts_on),active BOOLEAN NOT NULL,version BIGINT NOT NULL,PRIMARY KEY(tenant_id,branch_id,product_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES product(tenant_id,id));
CREATE TABLE salesperson(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,branch_id UUID NOT NULL,name VARCHAR(160) NOT NULL,commission_percent NUMERIC(5,2) NOT NULL CHECK(commission_percent>=0 AND commission_percent<=100),active BOOLEAN NOT NULL,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id));
CREATE TABLE loyalty_policy(tenant_id UUID NOT NULL,branch_id UUID NOT NULL,points_per_real NUMERIC(9,4) NOT NULL CHECK(points_per_real>=0 AND points_per_real<=1000),active BOOLEAN NOT NULL,version BIGINT NOT NULL,PRIMARY KEY(tenant_id,branch_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id));
CREATE TABLE sale_commercial(tenant_id UUID NOT NULL,sale_id UUID NOT NULL,salesperson_id UUID,customer_id UUID,commission_percent NUMERIC(5,2) NOT NULL,commission_amount NUMERIC(19,2) NOT NULL CHECK(commission_amount>=0),points NUMERIC(19,0) NOT NULL CHECK(points>=0),PRIMARY KEY(tenant_id,sale_id),FOREIGN KEY(tenant_id,sale_id) REFERENCES pos_sale(tenant_id,id),FOREIGN KEY(tenant_id,salesperson_id) REFERENCES salesperson(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customer(tenant_id,id));
CREATE TABLE commercial_ledger(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,branch_id UUID NOT NULL,sale_id UUID,salesperson_id UUID,customer_id UUID,source_id UUID NOT NULL,kind VARCHAR(20) NOT NULL CHECK(kind IN ('SALE','RETURN','CANCEL','REDEEM')),commission NUMERIC(19,2) NOT NULL,points NUMERIC(19,0) NOT NULL,note VARCHAR(500) NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,source_id,kind),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,sale_id) REFERENCES pos_sale(tenant_id,id),FOREIGN KEY(tenant_id,salesperson_id) REFERENCES salesperson(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customer(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES app_user(tenant_id,id));
CREATE INDEX ix_commercial_ledger_customer ON commercial_ledger(tenant_id,branch_id,customer_id,created_at);
CREATE TABLE commercial_rule_history(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,branch_id UUID NOT NULL,kind VARCHAR(30) NOT NULL,entity_id UUID NOT NULL,content TEXT NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES app_user(tenant_id,id));
CREATE INDEX ix_commercial_rule_history ON commercial_rule_history(tenant_id,branch_id,created_at);
